CREATE DATABASE IF NOT EXISTS student_management;
USE student_management;
CREATE TABLE IF NOT EXISTS admins(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(150) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL);
CREATE TABLE IF NOT EXISTS students(id INT AUTO_INCREMENT PRIMARY KEY,roll_number VARCHAR(40) UNIQUE NOT NULL,full_name VARCHAR(120) NOT NULL,email VARCHAR(150),department VARCHAR(100) NOT NULL,semester TINYINT,phone VARCHAR(25),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS attendance(id INT AUTO_INCREMENT PRIMARY KEY,student_id INT NOT NULL,attendance_date DATE NOT NULL,status ENUM('Present','Absent','Late') NOT NULL,UNIQUE KEY unique_student_day(student_id,attendance_date),FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE);
